fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64> {
    // The length of indices equals the length of each row of choices
    // For each position i:
    //   row_index = indices[i] (converted to usize)
    //   take choices[row_index][i]
    indices
        .iter()
        .enumerate()
        .map(|(i, &row_index)| {
            let r = row_index as usize;
            choices[r][i]
        })
        .collect()
}